1	-- 设备工时保养判定：H2（MODE=MySQL）自动建表脚本。
2	-- 所有时刻字段均为 UTC（TIMESTAMP WITH TIME ZONE），分钟数为非负整数。
3	
4	-- 设备主表：每台设备一行，版本号用于写操作乐观并发控制。
5	CREATE TABLE IF NOT EXISTS equipment (
6	    equipment_id VARCHAR(64) NOT NULL PRIMARY KEY,
7	    maintenance_period_minutes BIGINT NOT NULL,
8	    version BIGINT NOT NULL,
9	    created_at TIMESTAMP WITH TIME ZONE NOT NULL
10	);
11	COMMENT ON TABLE equipment IS '设备主表：每台设备一行';
12	COMMENT ON COLUMN equipment.equipment_id IS '设备唯一标识（客户端提供）';
13	COMMENT ON COLUMN equipment.maintenance_period_minutes IS '保养周期（分钟），正整数，登记后不可修改';
14	COMMENT ON COLUMN equipment.version IS '设备版本号，初始 1；新增读数/修订/完成保养均校验 expectedVersion 并加一';
15	COMMENT ON COLUMN equipment.created_at IS '登记时刻（UTC）';
16	
17	-- 工时读数当前值表：reading_id 设备内唯一，同设备同一采样时刻仅一条。
18	CREATE TABLE IF NOT EXISTS reading (
19	    equipment_id VARCHAR(64) NOT NULL,
20	    reading_id VARCHAR(64) NOT NULL,
21	    sampled_at TIMESTAMP WITH TIME ZONE NOT NULL,
22	    cumulative_minutes BIGINT NOT NULL,
23	    revision_no INT NOT NULL,
24	    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
25	    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
26	    PRIMARY KEY (equipment_id, reading_id),
27	    CONSTRAINT uq_reading_sampled_at UNIQUE (equipment_id, sampled_at)
28	);
29	COMMENT ON TABLE reading IS '工时读数当前值：按采样时刻排序后累计分钟须单调不减';
30	COMMENT ON COLUMN reading.equipment_id IS '所属设备标识';
31	COMMENT ON COLUMN reading.reading_id IS '读数标识，设备内唯一';
32	COMMENT ON COLUMN reading.sampled_at IS 'UTC 采样时刻；同设备同一时刻仅允许一条读数';
33	COMMENT ON COLUMN reading.cumulative_minutes IS '当前累计工时（分钟），非负整数，随修订更新';
34	COMMENT ON COLUMN reading.revision_no IS '当前修订号，初始 1，每次修订加一';
35	COMMENT ON COLUMN reading.created_at IS '读数登记时刻（UTC）';
36	COMMENT ON COLUMN reading.updated_at IS '最近一次修订时刻（UTC）';
37	
38	-- 读数修订历史：每次修订追加一行，保留全部历史值。
39	CREATE TABLE IF NOT EXISTS reading_revision (
40	    equipment_id VARCHAR(64) NOT NULL,
41	    reading_id VARCHAR(64) NOT NULL,
42	    revision_no INT NOT NULL,
43	    cumulative_minutes BIGINT NOT NULL,
44	    request_id VARCHAR(128) NOT NULL,
45	    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
46	    PRIMARY KEY (equipment_id, reading_id, revision_no)
47	);
48	COMMENT ON TABLE reading_revision IS '读数修订历史：revision_no=1 为初始登记值，其后每行对应一次修订';
49	COMMENT ON COLUMN reading_revision.equipment_id IS '所属设备标识';
50	COMMENT ON COLUMN reading_revision.reading_id IS '读数标识';
51	COMMENT ON COLUMN reading_revision.revision_no IS '修订号，从 1 开始递增';
52	COMMENT ON COLUMN reading_revision.cumulative_minutes IS '该修订版本的累计工时（分钟）';
53	COMMENT ON COLUMN reading_revision.request_id IS '产生该修订的请求 requestId';
54	COMMENT ON COLUMN reading_revision.created_at IS '该修订生效时刻（UTC）';
55	
56	-- 保养记录：锚定某读数的特定修订号，保存锚点时刻与工时快照，不允许删除。
57	CREATE TABLE IF NOT EXISTS maintenance (
58	    maintenance_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
59	    equipment_id VARCHAR(64) NOT NULL,
60	    reading_id VARCHAR(64) NOT NULL,
61	    anchor_revision_no INT NOT NULL,
62	    anchor_sampled_at TIMESTAMP WITH TIME ZONE NOT NULL,
63	    anchor_cumulative_minutes BIGINT NOT NULL,
64	    request_id VARCHAR(128) NOT NULL,
65	    completed_at TIMESTAMP WITH TIME ZONE NOT NULL
66	);
67	CREATE INDEX IF NOT EXISTS idx_maintenance_equipment ON maintenance (equipment_id, anchor_sampled_at);
68	COMMENT ON TABLE maintenance IS '保养记录：锚点时间须严格晚于上次保养锚点；作为锚点的读数不可再修订';
69	COMMENT ON COLUMN maintenance.maintenance_id IS '保养记录自增主键';
70	COMMENT ON COLUMN maintenance.equipment_id IS '所属设备标识';
71	COMMENT ON COLUMN maintenance.reading_id IS '锚点读数标识';
72	COMMENT ON COLUMN maintenance.anchor_revision_no IS '锚点读数在保养完成时的修订号';
73	COMMENT ON COLUMN maintenance.anchor_sampled_at IS '锚点读数的 UTC 采样时刻（快照）';
74	COMMENT ON COLUMN maintenance.anchor_cumulative_minutes IS '锚点读数在保养完成时的累计工时快照（分钟）';
75	COMMENT ON COLUMN maintenance.request_id IS '完成保养请求的 requestId';
76	COMMENT ON COLUMN maintenance.completed_at IS '保养完成登记时刻（UTC）';
77	
78	-- 幂等去重表：requestId 全局唯一；仅成功结果占键，失败回滚不占键。
79	CREATE TABLE IF NOT EXISTS idempotency_request (
80	    request_id VARCHAR(128) NOT NULL PRIMARY KEY,
81	    operation VARCHAR(48) NOT NULL,
82	    request_fingerprint VARCHAR(512) NOT NULL,
83	    response_body CLOB NOT NULL,
84	    created_at TIMESTAMP WITH TIME ZONE NOT NULL
85	);
86	COMMENT ON TABLE idempotency_request IS '写操作幂等去重：同键同参重放原成功结果，同键异参返回 409';
87	COMMENT ON COLUMN idempotency_request.request_id IS '全局唯一请求标识';
88	COMMENT ON COLUMN idempotency_request.operation IS '操作类型（登记设备/新增读数/修订/完成保养）';
89	COMMENT ON COLUMN idempotency_request.request_fingerprint IS '业务参数指纹（不含 requestId），用于同键异参判定';
90	COMMENT ON COLUMN idempotency_request.response_body IS '原成功响应报文（JSON），重放时原样返回';
91	COMMENT ON COLUMN idempotency_request.created_at IS '首次成功处理时刻（UTC）';
